"""Read-only assertion for audit events generated by the distinct browser tests."""
import os
import sys

os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'config.settings')
import django  # noqa: E402
django.setup()

from followup.models import AuditEvent  # noqa: E402

events = set(AuditEvent.objects.filter(actor__username='qa_e2e_owner', outcome='success')
             .values_list('event', flat=True))
required = {'consultation.create', 'measurement.create', 'note.create', 'document.upload'}
missing = required - events
if missing:
    sys.exit(f'Missing expected successful audit events: {sorted(missing)}')
print('Audit events verified:', ', '.join(sorted(required)))
